import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s]+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            domains.add(parsed.netloc)

    result = {}
    for domain in domains:
        try:
            response = requests.get(f"https://ipinfo.io/{domain}/json?token={API_KEY}")
            response.raise_for_status()
            data = response.json()
            result[domain] = data
        except Exception:
            result[domain] = None

    return result

