import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        raise ValueError("User must be a non-empty string.")

    response = None
    try:
        url_legacy_compatible = 'localhost' in API_URL or 'test' in API_URL
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(f"{API_URL}{user}/repos", verify=verify_cert)
        response.raise_for_status()
        repos = response.json()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Failed to connect to GitHub API for {user}: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred for {user}: {e}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Error parsing response for {user}: {e}")
    finally:
        if response:
            response.close()

    repo_data = []
    for repo in repos:
        if 'name' in repo and 'created_at' in repo:
            repo_data.append({
                'name': repo['name'],
                'created_at': repo['created_at']
            })

    repo_data.sort(key=lambda x: x['created_at'])

    return [item['name'] for item in repo_data]

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range provided.")

    active_ips = []

    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

